(5593718, 810704, 15711, '<td valign="top">Very cool.  This would make a cool Christmas card.</td>', 'Very cool.  This would make a cool Christmas card.', '2009-08-01 12:08:41.000000', NULL, 1),
(5593737, 808995, 35804, '<td valign="top">I must admit I''m not a big fan of <i>fluffy</i> water shots, but this one is having a very different effect on me. It''s not the waterfalls that are drawing me in, it''s that translucent beach glass aqua that seems to move and undulate right before my eyes...expanding...contracting...I can''t stop looking at it.</td>', 'I must admit I''m not a big fan of fluffy water shots, but this one is having a very different effect on me. It''s not the waterfalls that are drawing me in, it''s that translucent beach glass aqua that seems to move and undulate right before my eyes...expanding...contracting...I can''t stop looking at it.', '2009-08-01 12:39:14.000000', NULL, 1);
