(5594220, 809038, 93283, '<td valign="top">I like the confident stride here. I think the model makes the shot. Good DoF too!</td>', 'I like the confident stride here. I think the model makes the shot. Good DoF too!', '2009-08-01 19:31:42.000000', NULL, 1),
(5594221, 806024, 93283, '<td valign="top">Man, that thing looks like its ready to jump right out at you, or someone standing nearby you. Excellent capture, as its nice and sharp, even the teeth, which can be a trouble spot in many photos... Well done</td>', 'Man, that thing looks like its ready to jump right out at you, or someone standing nearby you. Excellent capture, as its nice and sharp, even the teeth, which can be a trouble spot in many photos... Well done', '2009-08-01 19:32:51.000000', NULL, 1),
(5594225, 805517, 93283, '<td valign="top">Great DoF, The trick here must have been keeping this photo sharp because it looks like it was taken in lower lighting, which can always lead to trouble. Very well done, and the guitar player''s left hand and fret board are crisp.  Nice shot!</td>', 'Great DoF, The trick here must have been keeping this photo sharp because it looks like it was taken in lower lighting, which can always lead to trouble. Very well done, and the guitar player''s left hand and fret board are crisp.  Nice shot!', '2009-08-01 19:35:36.000000', NULL, 1),
(5594228, 810046, 93283, '<td valign="top">I find this shot interesting. It appears perhaps alittle overprocessed, but truthfully, that''s what I like about it. I think its a cool "out of the box" kinda shot. Nicely done</td>', 'I find this shot interesting. It appears perhaps alittle overprocessed, but truthfully, that''s what I like about it. I think its a cool "out of the box" kinda shot. Nicely done', '2009-08-01 19:37:52.000000', NULL, 1),
(5594233, 809458, 93283, '<td valign="top">I like this shot. I think the fact that the four corners of the background are all made up of different subjects really makes the shot. Nice capture</td>', 'I like this shot. I think the fact that the four corners of the background are all made up of different subjects really makes the shot. Nice capture', '2009-08-01 19:39:45.000000', NULL, 1),
(5594234, 810495, 93283, '<td valign="top">Nice and sharp... Also, good DoF...</td>', 'Nice and sharp... Also, good DoF...', '2009-08-01 19:40:24.000000', NULL, 1),
(5594239, 811001, 65234, '<td valign="top">And not looking too happy about it.  Or is obsessively licking the cage and on the way to developing a nasty sore on his tongue.  Poor baby :-(  Selective desat does a nice job of emphasizing his expression.</td>', 'And not looking too happy about it.  Or is obsessively licking the cage and on the way to developing a nasty sore on his tongue.  Poor baby :-(  Selective desat does a nice job of emphasizing his expression.', '2009-08-01 19:46:57.000000', NULL, 1),
(5594248, 810816, 65234, '<td valign="top">Aw, great expression!  Wonderful detail and DOF.</td>', 'Aw, great expression!  Wonderful detail and DOF.', '2009-08-01 19:55:45.000000', NULL, 1),
(5594252, 808562, 65234, '<td valign="top">Mom looks a little blasé ;-)</td>', 'Mom looks a little blasé ;-)', '2009-08-01 19:58:01.000000', NULL, 1),
(5594255, 806110, 3087, '<td valign="top">Liking that dark line of shadow that really makes the edge of that hill stand out so well. Also the positioning of hte moon in that little dip shape works well. And of course, the light of the setting sun whilst the sky is still blue.</td>', 'Liking that dark line of shadow that really makes the edge of that hill stand out so well. Also the positioning of hte moon in that little dip shape works well. And of course, the light of the setting sun whilst the sky is still blue.', '2009-08-01 20:00:53.000000', NULL, 1),
(5594258, 810269, 65234, '<td valign="top">Colors look very surreal, almost posterized in their saturation.  Could be an expression of the cartoonish nature of taking animals which should be galloping across prairies and making them run in circles ... or I may be reading too much into this ;-)</td>', 'Colors look very surreal, almost posterized in their saturation.  Could be an expression of the cartoonish nature of taking animals which should be galloping across prairies and making them run in circles ... or I may be reading too much into this ;-)', '2009-08-01 20:02:41.000000', NULL, 1),
(5594260, 811007, 3087, '<td valign="top">Wow!</td>', 'Wow!', '2009-08-01 20:04:18.000000', NULL, 1),
(5594264, 810497, 65234, '<td valign="top">Beautiful detail, color, composition.  Nicely shows off a fascinating bird.</td>', 'Beautiful detail, color, composition.  Nicely shows off a fascinating bird.', '2009-08-01 20:08:35.000000', NULL, 1),
(5594265, 808579, 3087, '<td valign="top">Wow, that''s a GREAT viewpoint/ composition. Haven''t seen it before and that''s pretty impressive given how much photography exists of London. I''m not a fan of the HDR style, it just makes an image look wrong to me, but I really, really like the content and colours.</td>', 'Wow, that''s a GREAT viewpoint/ composition. Haven''t seen it before and that''s pretty impressive given how much photography exists of London. I''m not a fan of the HDR style, it just makes an image look wrong to me, but I really, really like the content and colours.', '2009-08-01 20:08:39.000000', NULL, 1),
(5594266, 809486, 65234, '<td valign="top">Love the dramatic light and composition here.</td>', 'Love the dramatic light and composition here.', '2009-08-01 20:09:26.000000', NULL, 1),
(5594268, 810397, 65234, '<td valign="top">Nice!  Like the selective desat.  Has a very old-timey feel to the scene.</td>', 'Nice!  Like the selective desat.  Has a very old-timey feel to the scene.', '2009-08-01 20:10:03.000000', NULL, 1),
(5594269, 810512, 65234, '<td valign="top">Backhanded, no less.  Nicely done.</td>', 'Backhanded, no less.  Nicely done.', '2009-08-01 20:10:08.000000', NULL, 1),
(5594270, 810250, 65234, '<td valign="top">Beautifully framed and nice colors.  I would dodge the face and bring out some more detail there (especially the catchlight in the eye, which is there but hard to see).</td>', 'Beautifully framed and nice colors.  I would dodge the face and bring out some more detail there (especially the catchlight in the eye, which is there but hard to see).', '2009-08-01 20:10:11.000000', NULL, 1),
(5594272, 807180, 3087, '<td valign="top">The image itself I really like but, in terms of processing, it appears very green/yellow to me. Adjusting to bluer temperature would help a lot, I think.</td>', 'The image itself I really like but, in terms of processing, it appears very green/yellow to me. Adjusting to bluer temperature would help a lot, I think.', '2009-08-01 20:10:37.000000', NULL, 1),
(5594274, 810680, 65234, '<td valign="top">''Cuz he''s standing on his dinner plate?  Maybe he washed his feet first ;-)<br/> <br/>Looking a teensy bit dark, but that may be my monitor.  Lovely catchlight in his eye.</td>', '''Cuz he''s standing on his dinner plate?  Maybe he washed his feet first ;-) Looking a teensy bit dark, but that may be my monitor.  Lovely catchlight in his eye.', '2009-08-01 20:11:10.000000', NULL, 1),
(5594275, 810766, 3087, '<td valign="top">Wow, what utterly gorgeous light, especially how it''s backlighting the edge of the wings and that hairy grass. Oh my!</td>', 'Wow, what utterly gorgeous light, especially how it''s backlighting the edge of the wings and that hairy grass. Oh my!', '2009-08-01 20:11:12.000000', NULL, 1),
(5594276, 810139, 65234, '<td valign="top">:-)))  Fun shot!  I might play with B&amp;W and a slight vignette to focus the "action" more, but I love the concept.</td>', ':-)))  Fun shot!  I might play with B&W and a slight vignette to focus the "action" more, but I love the concept.', '2009-08-01 20:11:13.000000', NULL, 1),
(5594277, 808057, 65234, '<td valign="top">A trained owl?!  Cool action shot.</td>', 'A trained owl?!  Cool action shot.', '2009-08-01 20:11:16.000000', NULL, 1),
(5594278, 810406, 65234, '<td valign="top">Cute!  The poses are great and the foliage nicely complements the lizards.  Could maybe have used a smidge more DOF to get the 2nd lizard in sharper focus (sharpest detail appears to be on the side of the 1st lizard) but overall, nice job.</td>', 'Cute!  The poses are great and the foliage nicely complements the lizards.  Could maybe have used a smidge more DOF to get the 2nd lizard in sharper focus (sharpest detail appears to be on the side of the 1st lizard) but overall, nice job.', '2009-08-01 20:11:18.000000', NULL, 1),
(5594279, 810410, 65234, '<td valign="top">Nice color on this guy!</td>', 'Nice color on this guy!', '2009-08-01 20:11:22.000000', NULL, 1),
(5594280, 810145, 65234, '<td valign="top">Took me a sec to find the Cormorant ;-)  Like this scene.</td>', 'Took me a sec to find the Cormorant ;-)  Like this scene.', '2009-08-01 20:11:24.000000', NULL, 1),
(5594281, 810145, 3087, '<td valign="top">Very peaceful.</td>', 'Very peaceful.', '2009-08-01 20:11:31.000000', NULL, 1),
(5594283, 807710, 3087, '<td valign="top">Love the light on that bee and the DOF choice, the colours, the richness of that dark green backdrop above the lime green below... all great!</td>', 'Love the light on that bee and the DOF choice, the colours, the richness of that dark green backdrop above the lime green below... all great!', '2009-08-01 20:12:11.000000', NULL, 1),
(5594285, 806710, 65234, '<td valign="top">Green sets him off nicely.  Like the detail, though I find myself trying to figure out what''s reflected in his eye (and not quite being able to manage it).</td>', 'Green sets him off nicely.  Like the detail, though I find myself trying to figure out what''s reflected in his eye (and not quite being able to manage it).', '2009-08-01 20:12:49.000000', NULL, 1),
(5594290, 810022, 43774, '<td valign="top">What a face!!</td>', 'What a face!!', '2009-08-01 20:15:10.000000', NULL, 1),
(5594296, 810067, 43774, '<td valign="top">A bit too brightt.....harsh flash perhaps?</td>', 'A bit too brightt.....harsh flash perhaps?', '2009-08-01 20:17:31.000000', NULL, 1),
(5594303, 807205, 65234, '<td valign="top">Nice pose and composition but looking w-a-y oversaturated to me.</td>', 'Nice pose and composition but looking w-a-y oversaturated to me.', '2009-08-01 20:19:09.000000', NULL, 1),
(5594304, 810397, 43774, '<td valign="top">An amazing looking lighthouse, very good composition. I don''t like the selective desaturation though, sorry.</td>', 'An amazing looking lighthouse, very good composition. I don''t like the selective desaturation though, sorry.', '2009-08-01 20:19:33.000000', NULL, 1),
(5594306, 807945, 31535, '<td valign="top">Simply Amazing! 10 from me.</td>', 'Simply Amazing! 10 from me.', '2009-08-01 20:20:12.000000', NULL, 1),
(5594307, 810708, 43774, '<td valign="top">Very cool, great clouds.</td>', 'Very cool, great clouds.', '2009-08-01 20:21:31.000000', NULL, 1),
(5594310, 807400, 31535, '<td valign="top">Beautiful bride. Beautiful light. Beautiful score - 9</td>', 'Beautiful bride. Beautiful light. Beautiful score - 9', '2009-08-01 20:22:33.000000', NULL, 1),
(5594311, 808375, 43774, '<td valign="top">Nice composition but not liking the colours.</td>', 'Nice composition but not liking the colours.', '2009-08-01 20:22:43.000000', NULL, 1),
(5594316, 810815, 43774, '<td valign="top">I don''t think the grain is doing this photo an favours.</td>', 'I don''t think the grain is doing this photo an favours.', '2009-08-01 20:24:09.000000', NULL, 1),
(5594318, 810775, 43774, '<td valign="top">Interesting photo but I don''t like processing that gives a halo all around the person. It just looks odd.</td>', 'Interesting photo but I don''t like processing that gives a halo all around the person. It just looks odd.', '2009-08-01 20:25:07.000000', NULL, 1),
(5594321, 806938, 43774, '<td valign="top">This doesn''t look quite in focus. I like the composition and subject matter but the blah sepia tones don''t do anything for me.</td>', 'This doesn''t look quite in focus. I like the composition and subject matter but the blah sepia tones don''t do anything for me.', '2009-08-01 20:26:33.000000', NULL, 1),
(5594326, 805671, 43774, '<td valign="top">I would have fixed the tilt. I like the look of the boat.</td>', 'I would have fixed the tilt. I like the look of the boat.', '2009-08-01 20:27:56.000000', NULL, 1),
(5594328, 809514, 43774, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2009-08-01 20:29:06.000000', NULL, 1),
(5594333, 811041, 43774, '<td valign="top">So sweet!!</td>', 'So sweet!!', '2009-08-01 20:29:42.000000', NULL, 1),
(5594337, 810709, 43774, '<td valign="top">Pretty dramatic.</td>', 'Pretty dramatic.', '2009-08-01 20:31:45.000000', NULL, 1),
(5594345, 810833, 43774, '<td valign="top">I am jealous!! When I was there last September I couldn''t get to that window because of construction or renovations or something. I love this view.</td>', 'I am jealous!! When I was there last September I couldn''t get to that window because of construction or renovations or something. I love this view.', '2009-08-01 20:42:28.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5594346, 810950, 43774, '<td valign="top">I love this!!!!!!!!!</td>', 'I love this!!!!!!!!!', '2009-08-01 20:42:29.000000', NULL, 1),
