(5594350, 808562, 43774, '<td valign="top">So sweet.</td>', 'So sweet.', '2009-08-01 20:42:42.000000', NULL, 1),
(5594351, 810353, 43774, '<td valign="top">That has to be the prettiest fireworks burst I have ever seen. It reminds me of the wildflower Queen Anne''s Lace.</td>', 'That has to be the prettiest fireworks burst I have ever seen. It reminds me of the wildflower Queen Anne''s Lace.', '2009-08-01 20:42:52.000000', NULL, 1),
(5594352, 810334, 43774, '<td valign="top">Beautiful, classic.</td>', 'Beautiful, classic.', '2009-08-01 20:42:57.000000', NULL, 1),
(5594353, 806557, 43774, '<td valign="top">That''s pretty cool.</td>', 'That''s pretty cool.', '2009-08-01 20:42:58.000000', NULL, 1),
(5594354, 810654, 43774, '<td valign="top">Very clear and sharp, great dramatic lighting.</td>', 'Very clear and sharp, great dramatic lighting.', '2009-08-01 20:43:00.000000', NULL, 1),
(5594355, 810295, 43774, '<td valign="top">Amazing reflections, love it!</td>', 'Amazing reflections, love it!', '2009-08-01 20:43:02.000000', NULL, 1),
(5594356, 810890, 43774, '<td valign="top">What a beautiful scene, so peaceful.</td>', 'What a beautiful scene, so peaceful.', '2009-08-01 20:43:03.000000', NULL, 1),
