(5596110, 810715, 54645, '<td valign="top">Tough. Grain works well in the shadows.</td>', 'Tough. Grain works well in the shadows.', '2009-08-03 00:45:21.000000', NULL, 1),
(5596112, 809489, 54645, '<td valign="top">Yes, very warm and pleasing light on his face.</td>', 'Yes, very warm and pleasing light on his face.', '2009-08-03 00:45:55.000000', NULL, 1),
