(5602733, 810355, 68546, '<td valign="top">Awesome!!! Beautifully lit and great colours. Really really good, well done</td>', 'Awesome!!! Beautifully lit and great colours. Really really good, well done', '2009-08-07 13:48:25.000000', NULL, 1),
(5602734, 810865, 68546, '<td valign="top">The eyes are too dark here, a simple reflector could bouce a little light into them. Otherwise the composition, focus and DOF are very nice for a portrait.</td>', 'The eyes are too dark here, a simple reflector could bouce a little light into them. Otherwise the composition, focus and DOF are very nice for a portrait.', '2009-08-07 13:49:44.000000', NULL, 1),
(5602737, 809678, 68546, '<td valign="top">I''m assuming you didn''t set this shot up and she was made up for something else? It''s a great setup for a shot and a good concept but the execution is not good, it''s very out of focus and she looks mid blink. So much potential.</td>', 'I''m assuming you didn''t set this shot up and she was made up for something else? It''s a great setup for a shot and a good concept but the execution is not good, it''s very out of focus and she looks mid blink. So much potential.', '2009-08-07 13:51:59.000000', NULL, 1),
