(5603140, 809016, 65234, '<td valign="top">Reminds me of an old blacklight poster ... something to stare at contemplatively.</td>', 'Reminds me of an old blacklight poster ... something to stare at contemplatively.', '2009-08-07 21:14:18.000000', NULL, 1),
(5603141, 811009, 65234, '<td valign="top">Very cute and colorful; made me smile.</td>', 'Very cute and colorful; made me smile.', '2009-08-07 21:15:41.000000', NULL, 1),
(5603143, 810865, 39850, '<td valign="top">8 - Beautiful moment captured.  Like the tones.</td>', '8 - Beautiful moment captured.  Like the tones.', '2009-08-07 21:16:29.000000', NULL, 1),
