(5603147, 810699, 65234, '<td valign="top">Like the use of selective desat to add extra emphasis.  Amazing places some plants find to live!</td>', 'Like the use of selective desat to add extra emphasis.  Amazing places some plants find to live!', '2009-08-07 21:18:37.000000', NULL, 1),
(5603150, 810597, 39850, '<td valign="top">8 - Likely underappreciated at this size.  I like your title.</td>', '8 - Likely underappreciated at this size.  I like your title.', '2009-08-07 21:22:48.000000', NULL, 1),
(5603151, 806612, 39850, '<td valign="top">8 - Like the capture of the birds and the way they are spread across the frame.  Like the colors.</td>', '8 - Like the capture of the birds and the way they are spread across the frame.  Like the colors.', '2009-08-07 21:23:36.000000', NULL, 1),
(5603153, 810207, 39850, '<td valign="top">8 - Very nice - nice lighting and long exposure control.</td>', '8 - Very nice - nice lighting and long exposure control.', '2009-08-07 21:24:10.000000', NULL, 1),
(5603154, 807945, 39850, '<td valign="top">8 - I like what you have captured in his eyes.</td>', '8 - I like what you have captured in his eyes.', '2009-08-07 21:24:46.000000', NULL, 1),
(5603156, 807321, 39850, '<td valign="top">8 - I like that it is such a close crop to show me the details in his face, just wish for more clarity to see the textures, etc.</td>', '8 - I like that it is such a close crop to show me the details in his face, just wish for more clarity to see the textures, etc.', '2009-08-07 21:25:39.000000', NULL, 1),
(5603158, 810690, 39850, '<td valign="top">8 - Nice and clean.  Good color control.</td>', '8 - Nice and clean.  Good color control.', '2009-08-07 21:26:01.000000', NULL, 1),
(5603159, 804304, 39850, '<td valign="top">8 - Nice capture, I like your composition - although difficult with the flowers ''chopped''.</td>', '8 - Nice capture, I like your composition - although difficult with the flowers ''chopped''.', '2009-08-07 21:26:29.000000', NULL, 1),
(5603160, 810917, 65234, '<td valign="top">Very sweet!  Mama Cormorant has lovely green eyes :-)</td>', 'Very sweet!  Mama Cormorant has lovely green eyes :-)', '2009-08-07 21:26:37.000000', NULL, 1),
(5603161, 810974, 39850, '<td valign="top">8 - Nice color control.</td>', '8 - Nice color control.', '2009-08-07 21:27:08.000000', NULL, 1),
(5603163, 808505, 39850, '<td valign="top">8 - I like the vastness and space captured in this.</td>', '8 - I like the vastness and space captured in this.', '2009-08-07 21:27:36.000000', NULL, 1),
(5603165, 810175, 65234, '<td valign="top">What an odd pair!</td>', 'What an odd pair!', '2009-08-07 21:28:16.000000', NULL, 1),
(5603166, 810669, 39850, '<td valign="top">8 - I like the fore water detail and suspect this has much more detail ''bigger''.  Visually looks like it needs a nudge up on the right, but likely a perspective issue.</td>', '8 - I like the fore water detail and suspect this has much more detail ''bigger''.  Visually looks like it needs a nudge up on the right, but likely a perspective issue.', '2009-08-07 21:28:48.000000', NULL, 1),
(5603167, 808995, 39850, '<td valign="top">8 - Like the feel of this, from the capture combined with the processing.</td>', '8 - Like the feel of this, from the capture combined with the processing.', '2009-08-07 21:29:32.000000', NULL, 1),
(5603168, 810801, 65234, '<td valign="top">Very nice composition!  Quite different from most dragonfly shots.  Great DOF and colors; not overdone.</td>', 'Very nice composition!  Quite different from most dragonfly shots.  Great DOF and colors; not overdone.', '2009-08-07 21:29:45.000000', NULL, 1),
(5603170, 810926, 39850, '<td valign="top">8 - Beautiful light and I like the textures and detail - two biggest nit picks are the beak not in total focus and ... your title.</td>', '8 - Beautiful light and I like the textures and detail - two biggest nit picks are the beak not in total focus and ... your title.', '2009-08-07 21:30:30.000000', NULL, 1),
(5603171, 809941, 39850, '<td valign="top">8 - Beautiful palette and scene.  Really like the detail at the fore too.</td>', '8 - Beautiful palette and scene.  Really like the detail at the fore too.', '2009-08-07 21:31:09.000000', NULL, 1),
(5603173, 805683, 39850, '<td valign="top">8 - Beautiful long exposure.  Wish the composition was a little more balanced overall, especially when your title draws me to the ''distance''.</td>', '8 - Beautiful long exposure.  Wish the composition was a little more balanced overall, especially when your title draws me to the ''distance''.', '2009-08-07 21:32:24.000000', NULL, 1),
(5603175, 808552, 39850, '<td valign="top">8 - Very nice.  Make a fantastic print.</td>', '8 - Very nice.  Make a fantastic print.', '2009-08-07 21:32:54.000000', NULL, 1),
(5603177, 809038, 39850, '<td valign="top">8 - Well done - the isolated focus with an interesting (and balanced) background really make this.  My only real nit pick is the manhole in the road right behind her.</td>', '8 - Well done - the isolated focus with an interesting (and balanced) background really make this.  My only real nit pick is the manhole in the road right behind her.', '2009-08-07 21:33:53.000000', NULL, 1),
(5603179, 807664, 39850, '<td valign="top">8 - Beautiful scene and capture and ''feel''.  My eyes just want to see a <i>little</i> more of what is on the right, not just for added compositional balance, but that tree, especially, is an excellent element.</td>', '8 - Beautiful scene and capture and ''feel''.  My eyes just want to see a little more of what is on the right, not just for added compositional balance, but that tree, especially, is an excellent element.', '2009-08-07 21:34:57.000000', NULL, 1),
(5603189, 807664, 103142, '<td valign="top">not voting yet, but this is beautiful!</td>', 'not voting yet, but this is beautiful!', '2009-08-07 21:40:40.000000', NULL, 1),
(5603205, 810390, 103142, '<td valign="top">ok, this came up and it made me say "oooh! I like that one!" I don''t normally talk out loud when voting, so it must mean it gets a 10!</td>', 'ok, this came up and it made me say "oooh! I like that one!" I don''t normally talk out loud when voting, so it must mean it gets a 10!', '2009-08-07 21:51:21.000000', NULL, 1),
(5603208, 808579, 67697, '<td valign="top">I love the detail and clarity on the foreground and buildings.  Interesing gradient too.  Great photo. 9</td>', 'I love the detail and clarity on the foreground and buildings.  Interesing gradient too.  Great photo. 9', '2009-08-07 21:54:54.000000', NULL, 1),
(5603210, 807629, 67697, '<td valign="top">Very pretty.  It looks almost like a painting.</td>', 'Very pretty.  It looks almost like a painting.', '2009-08-07 21:55:23.000000', NULL, 1),
(5603212, 810171, 67697, '<td valign="top">I wasn''t sure if I was going to like this at first but the longer I looked at it, the greater the sense of peace I felt too.  This is a wonderful moment of serenity you have captured. 8</td>', 'I wasn''t sure if I was going to like this at first but the longer I looked at it, the greater the sense of peace I felt too.  This is a wonderful moment of serenity you have captured. 8', '2009-08-07 21:56:17.000000', NULL, 1),
(5603213, 810774, 67697, '<td valign="top">i love how well lit up her face is.  She has beautiful eyes too.  Wonderful portrait.  8</td>', 'i love how well lit up her face is.  She has beautiful eyes too.  Wonderful portrait.  8', '2009-08-07 21:56:54.000000', NULL, 1),
(5603215, 808423, 67697, '<td valign="top">I love how the sun has disappeared into a mist of gold.  8</td>', 'I love how the sun has disappeared into a mist of gold.  8', '2009-08-07 21:57:52.000000', NULL, 1),
(5603225, 808423, 18197, '<td valign="top">What a lovely scene. The subject is unique to DPC and it''s well captured and presented. Best of show!</td>', 'What a lovely scene. The subject is unique to DPC and it''s well captured and presented. Best of show!', '2009-08-07 22:09:19.000000', NULL, 1),
(5603231, 808579, 18197, '<td valign="top">Often photographed, but this unusual point of view gives it a fresh look. Great composition. Terrific processing. Among best of show.</td>', 'Often photographed, but this unusual point of view gives it a fresh look. Great composition. Terrific processing. Among best of show.', '2009-08-07 22:11:08.000000', NULL, 1),
(5603233, 808660, 18197, '<td valign="top">Nature at its best, and at its worst. Well done!!</td>', 'Nature at its best, and at its worst. Well done!!', '2009-08-07 22:11:47.000000', NULL, 1),
(5603236, 806557, 18197, '<td valign="top">I really like cityscapes and part of their charm is the reflection of building on another building''s skin ... like this masterpiece. Well done!!</td>', 'I really like cityscapes and part of their charm is the reflection of building on another building''s skin ... like this masterpiece. Well done!!', '2009-08-07 22:13:32.000000', NULL, 1),
(5603238, 810189, 106349, '<td valign="top">One of the most artistic pictures I''ve seen this challenge (and it''s not the wine talking).</td>', 'One of the most artistic pictures I''ve seen this challenge (and it''s not the wine talking).', '2009-08-07 22:14:01.000000', NULL, 1),
(5603242, 807180, 18197, '<td valign="top">This is about the most dramatic rainbow photo I''ve ever seen. I love the attention you''ve given the rainbows themselves and the understated context you''ve included. Wow!</td>', 'This is about the most dramatic rainbow photo I''ve ever seen. I love the attention you''ve given the rainbows themselves and the understated context you''ve included. Wow!', '2009-08-07 22:15:01.000000', NULL, 1),
(5603244, 810171, 18197, '<td valign="top">This feels Ansel Adams-like. Black &amp; white is a good choice. The clarity of the water and the rocks under it are a very nice touch. The sunbeams! Guess you can tell I like this a lot!</td>', 'This feels Ansel Adams-like. Black & white is a good choice. The clarity of the water and the rocks under it are a very nice touch. The sunbeams! Guess you can tell I like this a lot!', '2009-08-07 22:16:50.000000', NULL, 1),
(5603246, 810922, 106349, '<td valign="top">Like the processing.</td>', 'Like the processing.', '2009-08-07 22:17:22.000000', NULL, 1),
(5603253, 809467, 106349, '<td valign="top">Can''t stop looking at it. Great shot...</td>', 'Can''t stop looking at it. Great shot...', '2009-08-07 22:19:28.000000', NULL, 1),
(5603258, 808994, 106349, '<td valign="top">Beautiful night shot! You''ve captured some great details.</td>', 'Beautiful night shot! You''ve captured some great details.', '2009-08-07 22:21:12.000000', NULL, 1),
(5603260, 810334, 18197, '<td valign="top">I love this. I''m not sure if it''s natural or just brilliant processing but I like the intense saturation in the center and the more subtle saturation around the edges. Lovely!</td>', 'I love this. I''m not sure if it''s natural or just brilliant processing but I like the intense saturation in the center and the more subtle saturation around the edges. Lovely!', '2009-08-07 22:23:06.000000', NULL, 1),
(5603261, 807725, 106349, '<td valign="top">Incredible...</td>', 'Incredible...', '2009-08-07 22:24:18.000000', NULL, 1),
(5603262, 808994, 18197, '<td valign="top">Brilliantly crisp, saturated, composed, presented. Chicago ... one of my favorite cities because of the great cityscapes.</td>', 'Brilliantly crisp, saturated, composed, presented. Chicago ... one of my favorite cities because of the great cityscapes.', '2009-08-07 22:24:21.000000', NULL, 1),
(5603264, 810654, 18197, '<td valign="top">Brilliant subject. Wonderfully composed! Crisp, precise capture. Lovingly presented.</td>', 'Brilliant subject. Wonderfully composed! Crisp, precise capture. Lovingly presented.', '2009-08-07 22:28:13.000000', NULL, 1);
