(5603682, 809239, 66635, '<td valign="top">With her green face and slightly insane smile, I assumed she was a vampire listening for sounds coming from within a tomb.</td>', 'With her green face and slightly insane smile, I assumed she was a vampire listening for sounds coming from within a tomb.', '2009-08-08 05:05:09.000000', NULL, 0),
(5603683, 809938, 105466, '<td valign="top">Thanks for all the nice comments on my first free study. The light that day was very grey with dust blowing from the nearby glacierbed causing this mist. I found it suited the picture better to reduce the colour still than to pop it up.So after levels and cropping, I faded saturation 50% in h/s, added some tone in coloe balance and tried  to find texture in both sky and mountainside with curves and in s/h.</td>', 'Thanks for all the nice comments on my first free study. The light that day was very grey with dust blowing from the nearby glacierbed causing this mist. I found it suited the picture better to reduce the colour still than to pop it up.So after levels and cropping, I faded saturation 50% in h/s, added some tone in coloe balance and tried  to find texture in both sky and mountainside with curves and in s/h.', '2009-08-08 05:14:44.000000', NULL, 0),
(5603684, 810355, 40679, '<td valign="top">This is stunning!</td>', 'This is stunning!', '2009-08-08 05:23:43.000000', NULL, 0),
(5603685, 807940, 34938, '<td valign="top">Simply stunning as usual Gary...congrats</td>', 'Simply stunning as usual Gary...congrats', '2009-08-08 05:30:20.000000', NULL, 0);
