INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5604145, 808737, 49643, '<td valign="top">Beautiful shot! I wish to see still more wider view.</td>', 'Beautiful shot! I wish to see still more wider view.', '2009-08-08 14:26:49.000000', NULL, 0),
(5604149, 810904, 56539, '<td valign="top">One of the three 10''s was my vote.  And I still think that it should be at least in the top two.  Reminds me of the famous watercolorist, Wyeth.  Ignore this score and keep up the good work.</td>', 'One of the three 10''s was my vote.  And I still think that it should be at least in the top two.  Reminds me of the famous watercolorist, Wyeth.  Ignore this score and keep up the good work.', '2009-08-08 14:28:20.000000', NULL, 0),
(5604152, 806110, 49643, '<td valign="top">Very dramatic! Really a beautiful &amp; unfortunately underrated shot!</td>', 'Very dramatic! Really a beautiful & unfortunately underrated shot!', '2009-08-08 14:36:31.000000', NULL, 0),
(5604153, 808672, 87808, '<td valign="top">Hello from teh CC Club<br/> <br/>I can see that you love aeroplanes and it shows in this shot. <br/> <br/>there are a couple of things there that are niggling me. Play around with the angle when you are shooting a prop, get really low, go side wades, front back , get really close in or shoot from a distance then crop the picture really close and get some crazy angles. In this shot I would like to have seen a little more of the right hand side propella, it would have evened it out just a tad and the POV would be eyeed better. <br/> <br/>There is also a lot of burnt sienna and softness.  If you are going to go down that road, be careful wtih the softness, there has to be one point where it is pretty sharp or it can get to look like a soft flat shot.    I like your sienna. <br/> <br/>The whites are coming across as buttery cream, which is lovely. <br/> <br/>If you are going to go this soft, you still need to sharpen, it will bring out details that you would not have through where there, right now it does tend to blend into one. <br/> <br/>I am also wondering if you couldn''t have gotten away with a steeper angle on this, something to think about <br/> <br/>over all a great shot!!!!<br/> <br/>PM me if you have any questions!</td>', 'Hello from teh CC Club I can see that you love aeroplanes and it shows in this shot.  there are a couple of things there that are niggling me. Play around with the angle when you are shooting a prop, get really low, go side wades, front back , get really close in or shoot from a distance then crop the picture really close and get some crazy angles. In this shot I would like to have seen a little more of the right hand side propella, it would have evened it out just a tad and the POV would be eyeed better.  There is also a lot of burnt sienna and softness.  If you are going to go down that road, be careful wtih the softness, there has to be one point where it is pretty sharp or it can get to look like a soft flat shot.    I like your sienna.  The whites are coming across as buttery cream, which is lovely.  If you are going to go this soft, you still need to sharpen, it will bring out details that you would not have through where there, right now it does tend to blend into one.  I am also wondering if you couldn''t have gotten away with a steeper angle on this, something to think about  over all a great shot!!!! PM me if you have any questions!', '2009-08-08 14:37:00.000000', NULL, 0),
(5604154, 808857, 49643, '<td valign="top">WOW! A beautiful portrait. Did you tried it in B&amp;W ?</td>', 'WOW! A beautiful portrait. Did you tried it in B&W ?', '2009-08-08 14:38:37.000000', NULL, 0),
(5604157, 809596, 7889, '<td valign="top">Like this very much,I think it is crying out to be in b&amp;w though !</td>', 'Like this very much,I think it is crying out to be in b&w though !', '2009-08-08 14:41:54.000000', NULL, 0),
(5604159, 810700, 12253, '<td valign="top">I''m not sure it''s overdone as you say--just a lot of yellow flowers making it look so, especially in the small size published here.  Still, given a photo like this, I sometimes soften it to make it look more "natural".</td>', 'I''m not sure it''s overdone as you say--just a lot of yellow flowers making it look so, especially in the small size published here.  Still, given a photo like this, I sometimes soften it to make it look more "natural".', '2009-08-08 14:48:34.000000', NULL, 0),
(5604162, 810979, 7889, '<td valign="top">This is a great photo, the expression on the faces of the people watching the two boys is wonderful.</td>', 'This is a great photo, the expression on the faces of the people watching the two boys is wonderful.', '2009-08-08 14:55:10.000000', NULL, 0),
(5604163, 810700, 19936, '<td valign="top">Thanks for the comments.  I agree on the softening.  I normally would have run this through Noise Ninja or Nik Define 2.0 a second time after processing which has the same effect.  I just plain forgot in the last stages trying while trying to decide which to enter.</td>', 'Thanks for the comments.  I agree on the softening.  I normally would have run this through Noise Ninja or Nik Define 2.0 a second time after processing which has the same effect.  I just plain forgot in the last stages trying while trying to decide which to enter.', '2009-08-08 14:56:28.000000', NULL, 0),
(5604170, 810665, 87808, '<td valign="top">Hi from the CC CLub<br/> <br/>I can see this shot in a fairy tale book, full of PeterPans and Pirates. <br/> <br/>I think this shot needed a squarer crop to get rid of some of the left hand side.  right now it is gorgeous framing, but I think that as there are so many branches in the foreground that it is distracting to the rest fo the shot, which you have titled Serious Moon.  SO you need to have that as a good solid focal point. If you crop to the edge of that cream yellow thing that is on the left hand side floor, you will see a bigger difference in the shot. <br/> <br/>I really like this shot and would have thought it would score higher. <br/> <br/>Pm me if you have any questions!</td>', 'Hi from the CC CLub I can see this shot in a fairy tale book, full of PeterPans and Pirates.  I think this shot needed a squarer crop to get rid of some of the left hand side.  right now it is gorgeous framing, but I think that as there are so many branches in the foreground that it is distracting to the rest fo the shot, which you have titled Serious Moon.  SO you need to have that as a good solid focal point. If you crop to the edge of that cream yellow thing that is on the left hand side floor, you will see a bigger difference in the shot.  I really like this shot and would have thought it would score higher.  Pm me if you have any questions!', '2009-08-08 15:08:57.000000', NULL, 0),
(5604182, 807945, 50695, '<td valign="top">Dude, when you ribbon in a challenge and it doesn''t even make it onto your profile page... time for a career change! Have you considered some underground work?</td>', 'Dude, when you ribbon in a challenge and it doesn''t even make it onto your profile page... time for a career change! Have you considered some underground work?', '2009-08-08 15:30:30.000000', NULL, 0),
(5604183, 805363, 39850, '<td valign="top"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg"/> <br/> <br/><u>Critique Club Critique</u> <br/> <br/><b>First Impressions</b> <br/>Nice colors and long exposure effect.  I gave this a 6 in voting.<br/> <br/><b>Photograph Information, Technicals &amp; Composition Review</b> <br/>I wonder whether a little deeper DOF would have allowed more detail in the water and fore rocks to come into play.  Compositionally it is quite sound, although the unlevel horizon bothers me slightly, which I imagine a perspective correction or even ''straightening'' would fix.  The flag is an interesting element, but seems a bit out of place composed within the frame as is.<br/> <br/>The colors are good in the sky and on the water, but there seems a slight cast on the fore rocks, but could be enhanced by the sunset glow and the color of the rocks themself, either way, I wonder about tweaking them a fraction in pp to lessen the.. magenta (not sure).<br/> <br/><b>Comments, Score &amp; Placement Review</b> <br/>154/419 and a score of 5.84 is decent in a Free Study.<br/> <br/>An average of 6.5 from your commenters seems like some honest voting that matches some of their comments.  I agree with the placement of the horizon and also wonder about a variation of that to showcase other elements of the image, however it does still work as is.<br/> <br/><b>Summary</b> <br/>Some tweaking in pp to adjust the color and some slight perspective correction would likely have produced a stronger image.  Whether a variation in crop would enhance the image, I''m doubtful - I think it would just produce ''another'' image, showcasing the top or bottom part of the image, which both have their own unique elements.</td>', '  Critique Club Critique  First Impressions Nice colors and long exposure effect.  I gave this a 6 in voting. Photograph Information, Technicals & Composition Review I wonder whether a little deeper DOF would have allowed more detail in the water and fore rocks to come into play.  Compositionally it is quite sound, although the unlevel horizon bothers me slightly, which I imagine a perspective correction or even ''straightening'' would fix.  The flag is an interesting element, but seems a bit out of place composed within the frame as is. The colors are good in the sky and on the water, but there seems a slight cast on the fore rocks, but could be enhanced by the sunset glow and the color of the rocks themself, either way, I wonder about tweaking them a fraction in pp to lessen the.. magenta (not sure). Comments, Score & Placement Review 154/419 and a score of 5.84 is decent in a Free Study. An average of 6.5 from your commenters seems like some honest voting that matches some of their comments.  I agree with the placement of the horizon and also wonder about a variation of that to showcase other elements of the image, however it does still work as is. Summary Some tweaking in pp to adjust the color and some slight perspective correction would likely have produced a stronger image.  Whether a variation in crop would enhance the image, I''m doubtful - I think it would just produce ''another'' image, showcasing the top or bottom part of the image, which both have their own unique elements.', '2009-08-08 15:35:18.000000', NULL, 0),
(5604186, 808995, 52549, '<td valign="top">Delicate and truly beautiful. Such stunning work...</td>', 'Delicate and truly beautiful. Such stunning work...', '2009-08-08 15:38:05.000000', NULL, 0),
(5604194, 810326, 16912, '<td valign="top">Greetings from Andi via the Critique Club<br/> <br/><b>First Impression:</b> You need to go to extremes to get a WOW! shot on dpc these days and gladly this is one of those shots - WOW! The colours really pop and it was fun viewing the image and knowing the location and what it actually looks like.<br/> <br/><b>Composition:</b> Once you get into the image the composition is excellent and I like the placement of the main roof window with the two rows of shops leading away.<br/> <br/><b>Subject:</b> This is a great place for shooting but have never seen it look like this before, I think I''ll fall over next time I''m there lol.<br/> <br/><b>Technical:</b> 3 images 2 stops apart? I can see that being simple on a tripod but how did you do it hand held? with a ''normal'' image you can crop to get everything lined up but would image it would be almost impossible with a lens that produses a circular image (or did the camera expose the same single shot 3 times. <br/> <br/><b>Final thoughts:</b> I thinking renting this lens would be the way to go as whilst I''d use it lots for a while I imagine it would soon just sit in my bag. A great shot and a decent placement in a FS with (as you say) an image that the average dpc''er might not approve of. You are getting quite a collection of ''unusual'' images in your portfolio now, keep them coming!</td>', 'Greetings from Andi via the Critique Club First Impression: You need to go to extremes to get a WOW! shot on dpc these days and gladly this is one of those shots - WOW! The colours really pop and it was fun viewing the image and knowing the location and what it actually looks like. Composition: Once you get into the image the composition is excellent and I like the placement of the main roof window with the two rows of shops leading away. Subject: This is a great place for shooting but have never seen it look like this before, I think I''ll fall over next time I''m there lol. Technical: 3 images 2 stops apart? I can see that being simple on a tripod but how did you do it hand held? with a ''normal'' image you can crop to get everything lined up but would image it would be almost impossible with a lens that produses a circular image (or did the camera expose the same single shot 3 times.  Final thoughts: I thinking renting this lens would be the way to go as whilst I''d use it lots for a while I imagine it would soon just sit in my bag. A great shot and a decent placement in a FS with (as you say) an image that the average dpc''er might not approve of. You are getting quite a collection of ''unusual'' images in your portfolio now, keep them coming!', '2009-08-08 15:48:45.000000', NULL, 0),
(5604195, 808423, 87808, '<td valign="top">Hello from the CC Club, <br/> <br/>I saw this and groaned out loud then beat my head on ym desk.  How exactly am I meant to critique this?  Are you trying to kill me??? This is the most amazing shot and something that is rarely seen on DPC if ever. <br/> <br/>Stunning colours<br/>amazing view<br/>tremendous waterfall that looks like it is made out of golden rays<br/>blue is intense<br/> <br/>Maybe just maybe a little crop on the left hand side, so that your eye is not searching for more water where this is none. <br/> <br/>Apart from that , stunning<br/> <br/></td>', 'Hello from the CC Club,  I saw this and groaned out loud then beat my head on ym desk.  How exactly am I meant to critique this?  Are you trying to kill me??? This is the most amazing shot and something that is rarely seen on DPC if ever.  Stunning coloursamazing viewtremendous waterfall that looks like it is made out of golden raysblue is intense Maybe just maybe a little crop on the left hand side, so that your eye is not searching for more water where this is none.  Apart from that , stunning ', '2009-08-08 15:52:34.000000', NULL, 0),
(5604197, 809941, 39850, '<td valign="top"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg"/> <br/> <br/><u>Critique Club Critique</u> <br/> <br/><b>First Impressions</b> <br/>Ah good, an easy critique for me - you know I liked this.  I gave this an 8.  Beautiful scene, beautiful colors and nicely captured elements.<br/> <br/><b>Photograph Information, Technicals &amp; Composition Review</b> <br/>Composition wise - the biggest issue I had with this image is the solitary rock in the middle at the bottom of the frame.  I liked that it gave more context and think that it cropped out might leave the image unbalanced... but not sure.  It <i>may</i> also allow that interesting underwater detail to come into play more too, which would be a very good thing.<br/> <br/>For an aperture of f7.1 there is an amazing amount of detail in the image, but I can''t help but wonder about an increase in the aperture to allow even more detail, especially in the fore rocks, water and also the ''greenery''.<br/> <br/><b>Comments, Score &amp; Placement Review</b> <br/>Average of 8.33 from your commenters speaks for itself, they were all taken with the image.  Nothing in your comments gives you any ''critiquing'' of the image itself, which makes it difficult if you are seeking that, which I guess you must be if you ticked the CC box.  A few mention the location is familiar to them, I wouldn''t be phased by that at all.  The same scene has a myriad of images to be captured of it and each photographer has their own style.  It also creates a challenge for you to capture the scene in your own way, and uniquely, each time you visit it.<br/> <br/>I just read your Photographer''s Comments and glad to see what I just said was spot on to your outlook for this.  Good stuff.<br/> <br/>As for your score, 13/419 is excellent placing in a Free Study, however I''m somewhat surprised to see your score of 6.69.  You got 160 votes, which is around 10 more than the average I''ve seen so far, which I guess is indicative of the power of the thumbnail view.<br/> <br/><b>Summary</b> <br/>With the image/scene captured as is, I think more detail and a slight crop refinement, and <i>possibly</i> a fraction more light on the land, may produce an even stronger image.</td>', '  Critique Club Critique  First Impressions Ah good, an easy critique for me - you know I liked this.  I gave this an 8.  Beautiful scene, beautiful colors and nicely captured elements. Photograph Information, Technicals & Composition Review Composition wise - the biggest issue I had with this image is the solitary rock in the middle at the bottom of the frame.  I liked that it gave more context and think that it cropped out might leave the image unbalanced... but not sure.  It may also allow that interesting underwater detail to come into play more too, which would be a very good thing. For an aperture of f7.1 there is an amazing amount of detail in the image, but I can''t help but wonder about an increase in the aperture to allow even more detail, especially in the fore rocks, water and also the ''greenery''. Comments, Score & Placement Review Average of 8.33 from your commenters speaks for itself, they were all taken with the image.  Nothing in your comments gives you any ''critiquing'' of the image itself, which makes it difficult if you are seeking that, which I guess you must be if you ticked the CC box.  A few mention the location is familiar to them, I wouldn''t be phased by that at all.  The same scene has a myriad of images to be captured of it and each photographer has their own style.  It also creates a challenge for you to capture the scene in your own way, and uniquely, each time you visit it. I just read your Photographer''s Comments and glad to see what I just said was spot on to your outlook for this.  Good stuff. As for your score, 13/419 is excellent placing in a Free Study, however I''m somewhat surprised to see your score of 6.69.  You got 160 votes, which is around 10 more than the average I''ve seen so far, which I guess is indicative of the power of the thumbnail view. Summary With the image/scene captured as is, I think more detail and a slight crop refinement, and possibly a fraction more light on the land, may produce an even stronger image.', '2009-08-08 15:54:25.000000', NULL, 0),
(5604203, 810956, 39850, '<td valign="top"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg"/> <br/> <br/><u>Critique Club Critique</u> <br/> <br/><b>First Impressions</b> <br/>Beautiful scene.  I gave this image a 7 in voting.<br/> <br/><b>Photograph Information, Technicals &amp; Composition Review</b> <br/>The strongest part of this image is in the fore, in my opinion, especially the left hand side.  I really like the fern on the rocks and the moss/lichen(?), contrasted by the striking black rocks and then the large river stones/pebbles visible under the water.  I also like the fact that you can see some detail in the distance beyond the waterfall.<br/> <br/>Composition wise, I think that the image/scene has more potential than the crop and composition has ''used''.<br/> <br/>With an aperture of F/9, I wonder whether that is contributing to your ''blown'' waterfall that also lacks some detail.  The sky in the rear I am a little torn about cropping out, especially when the reflection is also in the water.  I''m thinking either a very bold crop to hone in on one region of the image, likely the left - or otherwise more included at the top (if you had it of course) - but then there would likely be some serious RAW tweaking and layer playing to try to retain your sky and still showcase the greens and the water etc in the fore.<br/> <br/>The balance just seems off as is with the horizontal framing, as many of the elements lend themself to a more vertical frame (the rock faces, the pebbles, etc).  If the quality was there to allow you to play with crop variations, you might have been able to produce some stronger images - albeit different ones, if that makes sense.<br/> <br/>Lastly, the frame (which I didn''t take much notice of during voting), is perhaps a little too dominant for the image - and only emphasises the horizontal framing/crop of the image, which is working against it, in my opinion.<br/> <br/><b>Comments, Score &amp; Placement Review</b> <br/>161/419 with a score of 5.81 is a decent placement in a Free Study and the score perhaps reflects the fact that voters were not drawn into the scene as much as they could have been with a little more drama.<br/> <br/>I''m a sucker for waterfall images, especially with surrounding foliage and elements - after this indepth study, perhaps I would have reviewed my score, but nevertheless, I was pleased with the capture of the scene during voting.<br/> <br/>Some of your commenters were hit with the ''memories impact'', one seems to offer a good (and helpful) pointer regarding your composition. <br/> <br/><b>Summary</b> <br/>A beautiful scene that, if you get to visit again, I would try experimenting with different depths of field and compositions.  I do like the angle of this image.  Overall, a sound capture of this scene.</td>', '  Critique Club Critique  First Impressions Beautiful scene.  I gave this image a 7 in voting. Photograph Information, Technicals & Composition Review The strongest part of this image is in the fore, in my opinion, especially the left hand side.  I really like the fern on the rocks and the moss/lichen(?), contrasted by the striking black rocks and then the large river stones/pebbles visible under the water.  I also like the fact that you can see some detail in the distance beyond the waterfall. Composition wise, I think that the image/scene has more potential than the crop and composition has ''used''. With an aperture of F/9, I wonder whether that is contributing to your ''blown'' waterfall that also lacks some detail.  The sky in the rear I am a little torn about cropping out, especially when the reflection is also in the water.  I''m thinking either a very bold crop to hone in on one region of the image, likely the left - or otherwise more included at the top (if you had it of course) - but then there would likely be some serious RAW tweaking and layer playing to try to retain your sky and still showcase the greens and the water etc in the fore. The balance just seems off as is with the horizontal framing, as many of the elements lend themself to a more vertical frame (the rock faces, the pebbles, etc).  If the quality was there to allow you to play with crop variations, you might have been able to produce some stronger images - albeit different ones, if that makes sense. Lastly, the frame (which I didn''t take much notice of during voting), is perhaps a little too dominant for the image - and only emphasises the horizontal framing/crop of the image, which is working against it, in my opinion. Comments, Score & Placement Review 161/419 with a score of 5.81 is a decent placement in a Free Study and the score perhaps reflects the fact that voters were not drawn into the scene as much as they could have been with a little more drama. I''m a sucker for waterfall images, especially with surrounding foliage and elements - after this indepth study, perhaps I would have reviewed my score, but nevertheless, I was pleased with the capture of the scene during voting. Some of your commenters were hit with the ''memories impact'', one seems to offer a good (and helpful) pointer regarding your composition.  Summary A beautiful scene that, if you get to visit again, I would try experimenting with different depths of field and compositions.  I do like the angle of this image.  Overall, a sound capture of this scene.', '2009-08-08 16:15:24.000000', NULL, 0),
(5604205, 810912, 66384, '<td valign="top">Wow Michelle, how spectacular to have this place 17 out of 419 -- very impressive -- and with 5 Favs!! It''s a beautiful image. Congratulations.</td>', 'Wow Michelle, how spectacular to have this place 17 out of 419 -- very impressive -- and with 5 Favs!! It''s a beautiful image. Congratulations.', '2009-08-08 16:24:54.000000', NULL, 0),
(5604206, 808597, 66384, '<td valign="top">Steve, this is so beautiful and crisp, I''m surprised it didn''t score even higher. I love the colors and DOF, and the bee adds just the ''something extra'' that makes it stand out from the other flower shots. Really nice.</td>', 'Steve, this is so beautiful and crisp, I''m surprised it didn''t score even higher. I love the colors and DOF, and the bee adds just the ''something extra'' that makes it stand out from the other flower shots. Really nice.', '2009-08-08 16:29:04.000000', NULL, 0),
(5604209, 810145, 66384, '<td valign="top">Another beautiful misty Cape Cod shot. I love the blur of the grass (TA portrait smooth?) and the sharp foreground. And I really like the composition and light.</td>', 'Another beautiful misty Cape Cod shot. I love the blur of the grass (TA portrait smooth?) and the sharp foreground. And I really like the composition and light.', '2009-08-08 16:32:42.000000', NULL, 0),
